import {ToolRegistry} from './registry.js';
import {createChatOrchestrator} from '../chatOrchestrator.js';
import {PromptBuilder} from '../../infrastructure/builders/promptBuilder.js';
import {setLogger} from '../../shared/logger.js';
import type {Logger} from '../../shared/logger.js';
import type {AIProvider, MessageChunk, SendMessageParams, ToolResultMessage} from '../../types/ai.js';
import type {ChatSession} from '../../types/session.js';

const SENT_AT = '2026-01-01T00:00:00.000Z';

describe('ToolRegistry inputSchema validation acceptance', () => {
  afterEach(() => {
    setLogger(undefined);
  });

  it('rejects input missing a required property with a ToolResponse and never calls the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    const response = await registry.execute('get_weather', {});

    expect({
      executorCalls,
      mentionsRequiredField: response.result.includes('location') && /required/i.test(response.result),
    }).toEqual({
      executorCalls: 0,
      mentionsRequiredField: true,
    });
  });

  it('rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs', async () => {
    const recordedLogs: string[] = [];
    const recordLine = (category: string, message: string, fields?: Record<string, unknown>) => {
      recordedLogs.push(JSON.stringify({category, message, fields}));
    };
    const logger: Logger = {
      debug: recordLine,
      info: recordLine,
      warn: recordLine,
      error: recordLine,
    };
    setLogger(logger);

    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'ssn_lookup',
        description: 'Look up record by identifier',
        inputSchema: {
          type: 'object',
          properties: {ssn: {type: 'string'}},
          required: ['ssn'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'found';
      }
    );

    const response = await registry.execute('ssn_lookup', {ssn: 123456789});

    expect({
      executorCalls,
      mentionsField: response.result.includes('ssn'),
      mentionsExpectedType: response.result.includes('string'),
      leaksValueInResult: response.result.includes('123456789'),
      leaksValueInLogs: recordedLogs.some(line => line.includes('123456789')),
    }).toEqual({
      executorCalls: 0,
      mentionsField: true,
      mentionsExpectedType: true,
      leaksValueInResult: false,
      leaksValueInLogs: false,
    });
  });

  it('throws at register time naming the tool when a static inputSchema cannot be compiled', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_weather',
          description: 'Has an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {location: {type: 'not-a-json-schema-type'}},
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_weather/);
  });

  it('returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round', async () => {
    const registry = new ToolRegistry();
    const executorInputs: Array<Record<string, unknown>> = [];
    registry.register(
      () => ({
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      }),
      async input => {
        executorInputs.push(input);
        return `22C in ${String(input.location)}`;
      }
    );

    let firstRoundToolResult = '';
    let round = 0;
    const provider: AIProvider = {
      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
        round += 1;
        if (round === 1) {
          yield {type: 'tool_use', toolCall: {id: 'call-1', name: 'get_weather', input: {}}};
          yield {type: 'stop', stopReason: 'tool_use'};
          return;
        }
        if (round === 2) {
          const lastMessage = params.messages[params.messages.length - 1] as ToolResultMessage;
          firstRoundToolResult = lastMessage.content[0]?.content ?? '';
          yield {
            type: 'tool_use',
            toolCall: {id: 'call-2', name: 'get_weather', input: {location: 'Paris'}},
          };
          yield {type: 'stop', stopReason: 'tool_use'};
          return;
        }
        yield {type: 'text', text: '22C in Paris'};
        yield {type: 'stop', stopReason: 'end_turn'};
      },
      async generateStructured<T>(): Promise<T> {
        return {} as T;
      },
    };

    const orchestrator = createChatOrchestrator(
      provider,
      new PromptBuilder({identity: 'You are a test assistant.'}),
      registry
    );
    const session: ChatSession = {
      sessionId: 's-retry',
      userId: 'u1',
      entries: [{role: 'user', content: 'Weather in Paris?', timestamp: SENT_AT}],
    };

    const reply = await orchestrator.processMessage(session);

    expect({
      reply,
      executorInputs,
      firstAttemptRejectedForLocation:
        firstRoundToolResult.includes('location') && /required/i.test(firstRoundToolResult),
    }).toEqual({
      reply: '22C in Paris',
      executorInputs: [{location: 'Paris'}],
      firstAttemptRejectedForLocation: true,
    });
  });
});

import Ajv from 'ajv';
import type {ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validate?: ValidateFunction;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = new Ajv({strict: false, validateFormats: false});

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let validate: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      try {
        validate = this.ajv.compile(resolved.inputSchema);
      } catch (error) {
        throw new Error(`Invalid inputSchema for tool ${resolved.name}`, {cause: error});
      }
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute, validate});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

import {ToolRegistry} from './registry.js';

describe('ToolRegistry schema registration', () => {
  it('rejects an invalid static schema before registering the named tool', () => {
    const registry = new ToolRegistry();

    let errorMessage = '';
    try {
      registry.register(
        {
          name: 'broken_weather',
          description: 'Weather',
          inputSchema: {type: 'object', properties: {location: {type: 'not-a-json-schema-type'}}},
        },
        async () => 'unreachable'
      );
    } catch (error) {
      errorMessage = (error as Error).message;
    }

    expect({errorMessage, registered: registry.has('broken_weather')}).toEqual({
      errorMessage: expect.stringMatching(/broken_weather/),
      registered: false,
    });
  });
});

